import javax.swing.*;import java.awt.*;
public class Main {public static void main(String[]a){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Campus Fee Payment");JTextField id=new JTextField(12),amount=new JTextField(8);JLabel status=new JLabel("Enter details");JButton pay=new JButton("Pay"),clear=new JButton("Clear"),receipt=new JButton("Receipt");pay.addActionListener(e->{try{if(id.getText().isBlank())throw new IllegalArgumentException("Register number required");double v=Double.parseDouble(amount.getText());if(v<=0)throw new IllegalArgumentException("Amount must be positive");status.setText("Payment accepted: Rs."+v);}catch(Exception ex){JOptionPane.showMessageDialog(f,ex.getMessage());}});clear.addActionListener(e->{id.setText("");amount.setText("");status.setText("Cleared");});receipt.addActionListener(e->JOptionPane.showMessageDialog(f,status.getText()));JPanel p=new JPanel(new GridLayout(0,2,8,8));p.add(new JLabel("Register no"));p.add(id);p.add(new JLabel("Amount"));p.add(amount);p.add(pay);p.add(clear);p.add(receipt);p.add(status);f.add(p);f.pack();f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setVisible(true);});}}
